"""langsmith_setup.py  --  Lab 10 · Part D · connect YOUR free LangSmith account.   >>> YOU DO NOT EDIT THIS FILE <<<

Run:   python langsmith_setup.py          (or double-click  langsmith_1_setup.bat)

What it does (2 minutes):
  1. tells you the 4 clicks to make your free LangSmith account and an API key
  2. asks you to paste the key (nothing shows on screen while you paste: that is normal)
  3. saves it in the .env file INSIDE this lab folder (never pushed to GitHub)
  4. tests the connection and says OK or tells you what to fix
"""
import argparse
import getpass
import os
import re
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
ENV = HERE / ".env"
US, EU = "https://api.smith.langchain.com", "https://eu.api.smith.langchain.com"
REGIONS = {"us": US, "eu": EU, "apac": "https://apac.api.smith.langchain.com", "aws": "https://aws.api.smith.langchain.com"}
NAMES = {"us": "US (Google cloud)", "eu": "EU", "apac": "Asia-Pacific", "aws": "US (AWS)"}


def write_env(pairs):
    """Add or replace the LANGSMITH_ lines; keep every other line (Langfuse keys etc.)."""
    old = [ln for ln in (ENV.read_text(encoding="utf-8").splitlines() if ENV.is_file() else []) if not ln.startswith("LANGSMITH_")]
    ENV.write_text("\n".join(old + [f"{k}={v}" for k, v in pairs.items()]) + "\n", encoding="utf-8")


def test(key, endpoint):
    """Returns (ok, message). Never raises."""
    try:
        from langsmith import Client
    except ImportError:
        return False, "The langsmith package is missing. Run  python run.py  once (it installs the lab packages), then try again."
    try:
        c = Client(api_key=key, api_url=endpoint)
        next(iter(c.list_datasets(limit=1)), None)          # any call that needs a valid key
        return True, "Connected to LangSmith."
    except Exception as e:                                  # noqa: BLE001
        name, t = type(e).__name__.lower(), f"{type(e).__name__}: {e}"
        low = t.lower()
        if "connection" in name or any(w in low for w in ("proxy", "timed out", "timeout", "resolve", "ssl")):
            return False, "Could not reach smith.langchain.com from this machine. Open https://smith.langchain.com in the browser. If it is blocked, tell the trainer."
        if "auth" in name or any(w in low for w in ("403", "401", "forbidden", "unauthor", "invalid")):
            return False, ("LangSmith did not accept the key. Check that you copied the WHOLE key (starts with lsv2_). "
                           "The script already tried all 4 regions (US, EU, Asia-Pacific, AWS-US). If it still fails, create a new key and try again.")
        return False, t[:300]


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--eu", action="store_true", help="your LangSmith account is in the EU region (same as --region eu)")
    ap.add_argument("--region", choices=list(REGIONS), help="force one region; normally not needed, the script tries all four")
    ap.add_argument("--key", default="", help="the API key (if you do not give it, you are asked)")
    ap.add_argument("--check", action="store_true", help="only test the key that is already saved")
    a = ap.parse_args()

    try:
        from dotenv import dotenv_values
        saved = dotenv_values(ENV) if ENV.is_file() else {}
    except Exception:                                       # noqa: BLE001
        saved = {}
    forced = "eu" if a.eu else a.region
    endpoint = REGIONS[forced] if forced else (saved.get("LANGSMITH_ENDPOINT") or US)

    if a.check:
        key = saved.get("LANGSMITH_API_KEY", "") or os.environ.get("LANGSMITH_API_KEY", "")
        if not key:
            print("No LangSmith key saved yet. Run:  python langsmith_setup.py")
            return 1
        ok, msg = test(key, endpoint)
        print(("OK  " if ok else "FAIL  ") + msg)
        return 0 if ok else 1

    print("""
LANGSMITH · 4 clicks, then paste the key
  1. Open  https://smith.langchain.com  and sign up (Google, GitHub or email). The free plan is enough.
  2. Left menu: Settings  ->  API Keys  ->  Create API Key  (type: Personal Access Token). Give it any name.
  3. Press Copy. The key starts with  lsv2_  . It is shown ONCE.
  4. Come back to this window and paste it below (right-click or Ctrl+V; nothing shows on screen).
Do NOT post the key in the Teams chat or in GitHub.
""")
    key = a.key.strip() or getpass.getpass("Paste your LangSmith API key and press Enter: ").strip()
    key = re.sub(r"\s+", "", key).strip("'\"")
    if not key.startswith("lsv2_"):
        print("\nThat does not look like a LangSmith key (it should start with lsv2_). Copy it again from Settings > API Keys.")
        return 1

    who = re.sub(r"[^a-z0-9]+", "-", (os.environ.get("USERNAME") or os.environ.get("USER") or "me").lower()).strip("-") or "me"
    pairs = {"LANGSMITH_API_KEY": key, "LANGSMITH_PROJECT": f"askit-day10-{who}"}
    # LangSmith cannot tell which region a key belongs to, so we try them one by one (your chosen one first).
    order = ([forced] if forced else []) + [r for r in REGIONS if r != forced]
    ok, msg = False, ""
    for r in order:
        ok, msg = test(key, REGIONS[r])
        if ok:
            endpoint = REGIONS[r]
            print(f"\nFound your account in region: {NAMES[r]}.")
            break
        if "Could not reach" in msg or "package is missing" in msg:
            break                                           # a network / install problem: other regions will not help
    if ok and endpoint != US:
        pairs["LANGSMITH_ENDPOINT"] = endpoint
    write_env(pairs)
    print(f"\nSaved to {ENV.name} inside this lab folder (it is never pushed to GitHub).")
    print(("\nOK  " if ok else "\nFAIL  ") + msg)
    if ok:
        print("\nNext:  python langsmith_lab.py     (or double-click  langsmith_2_run.bat)")
    return 0 if ok else 1


if __name__ == "__main__":
    sys.exit(main())
